class HitClassifier(torch.nn.Module):
    def __init__(self, in_features):
        super().__init__()
        # Determine feature dimension; in_features may be Tensor or int
        if isinstance(in_features, torch.Tensor):
            self.in_dim = in_features.shape[1]  # total_hits x features
        else:
            self.in_dim = in_features

    def forward(self, batch_x):
        # batch_x: [total_hits, in_dim], last dimension is truth track_id
        preds = batch_x[:, -1]  # float tensor of track_id
        return preds.long()     # return as integer labels

def make_model(in_features):
    return HitClassifier(in_features)

